// Hard defaults you can change
const defaults = {
  bucket: "tools-bucket-cloudranger-30293812",
  prefix: "",  // optional path (no leading '/')
  ignoreFolders: ["processed","backups"],
  mainIndex: "security-findings",
  eventsIndex: "security-findings-events",
  processedPrefix: "processed/",             // where to move inside the same bucket
  processedBucket: "",                       // leave blank to keep same bucket

};

// Webhook sends either {body:{...}} or raw JSON
const raw = ($json.body && typeof $json.body === 'object') ? $json.body : $json;

// normalize ignoreFolders (array or comma-separated string)
let ignore = raw.ignoreFolders;
if (typeof ignore === 'string') {
  ignore = ignore.split(',').map(s => s.trim()).filter(Boolean);
}
if (!Array.isArray(ignore)) ignore = undefined;

// normalize prefix: strip slashes, then make folderKey (trailing slash if non-empty)
const p = (raw.prefix ?? defaults.prefix ?? '').toString().replace(/^\/+|\/+$/g,'');
const folderKey = p ? (p.endsWith('/') ? p : p + '/') : '';

// final config
const cfg = {
  ...defaults,
  ...raw,
  ...(ignore ? { ignoreFolders: ignore } : {}),
  prefix: p,          // clean, no slashes
  folderKey           // S3 "Folder Key" friendly
};

return [{ json: cfg }];

const cfg = $items('Apply Defaults')?.[0]?.json || {};
const ignore = (cfg.ignoreFolders || []).map(s => String(s).replace(/\/+$/,''));
const out = [];

for (const it of $items('List Files')) {
  const key = it.json.Key || it.json.key || '';
  if (!key.toLowerCase().endsWith('.json')) continue;

  // skip ignored folders (prefix match)
  if (ignore.some(pre => pre && (key === pre || key.startsWith(pre + '/')))) continue;

  // tag tool by path/name
  let tool = 'unknown';
  if (/zaproxy|zap/i.test(key)) tool = 'zaproxy';
  else if (/checkov/i.test(key)) tool = 'checkov';
  else if (/trufflehog/i.test(key)) tool = 'trufflehog';
  else if (/kubescape/i.test(key)) tool = 'kubescape';
  else if (/trivy/i.test(key)) tool = 'trivy';



  out.push({
    json: {
      bucket: cfg.bucket,
      key,
      tool,
      mainIndex: cfg.mainIndex,
      eventsIndex: cfg.eventsIndex
    }
  });
}

return out;

// ====== HELPERS ======
function fnv1a64Hex(str){
  let h=BigInt('0xcbf29ce484222325'), p=BigInt('0x100000001b3');
  for (let i=0;i<str.length;i++){ h^=BigInt(str.charCodeAt(i)); h=(h*p)&BigInt('0xFFFFFFFFFFFFFFFF'); }
  return h.toString(16).padStart(16,'0');
}
const fingerprintOf = (tool, signature) => fnv1a64Hex(JSON.stringify({ tool, signature }));

const ZAP_RISK = { "0":"Informational", "1":"Low", "2":"Medium", "3":"High" };
const ZAP_CONF = { "1":7, "2":4, "3":2, "4":1 }; // higher = more confident

const normParam   = (p) => (p === '' || p == null) ? null : String(p).trim().toLowerCase();
const normMethod  = (m) => { const v = (m || '').toString().trim().toUpperCase(); return v || null; };
const normPath    = (p) => p ? String(p).replace(/\\/g,'/').trim() : null;
function normRepoUrl(u){
  if (!u) return null;
  try {
    const url = new URL(u);
    url.hash = ''; url.search=''; // canonical
    return url.origin + url.pathname.replace(/\.git$/,'');
  } catch { return u; }
}
function sevCheckov(v){
  if (!v) return 'Medium';
  const s = String(v).toLowerCase();
  if (s.startsWith('info')) return 'Informational';
  if (s === 'low') return 'Low';
  if (s === 'medium') return 'Medium';
  if (s === 'high') return 'High';
  if (s === 'critical') return 'Critical';
  return 'Medium';
}
function sevTrivyLevel(s){
  const v = String(s || '').toLowerCase();
  if (v === 'critical') return 'Critical';
  if (v === 'high')     return 'High';
  if (v === 'medium')   return 'Medium';
  if (v === 'low')      return 'Low';
  if (v === 'unknown' || v === 'negligible') return 'Informational';
  return 'Medium';
}
function ksStatus(obj){
  // kubescape status can appear in different shapes
  return obj?.statusInfo?.status || obj?.status?.status || obj?.status || '';
}
function ksSeverityFromScore(score){
  const s = Number(score || 0);
  if (s >= 90) return 'High';
  if (s >= 60) return 'Medium';
  if (s >  0)  return 'Low';
  return 'Medium';
}

// ====== PARSERS ======

// --- ZAP (no site_owner in fingerprint)
function parseZap(scan){
  const sites  = Array.isArray(scan?.site) ? scan.site : [];
  const alerts = sites.flatMap(s => s?.alerts || []);
  const rows = [];

  for (const a of alerts){
    const title    = (a.alert || a.name || 'ZAP Finding').trim();
    const pluginid = String(a.pluginid || '').trim();
    const desc     = a.desc || a.description || '';
    const severity = ZAP_RISK[String(a.riskcode ?? '')] || ((a.riskdesc||'').split(' ')[0] || 'Informational');
    const conf     = ZAP_CONF[String(a.confidence ?? '')] ?? null;
    const cwe      = a.cweid || a.cwe || null;
    const siteOwner= a['Site Owner'] ?? a.site_owner ?? null;
    const guidance = (a.solution || a.references) ? [a.solution, a.references].filter(Boolean).join(' | ') : null;

    const inst = Array.isArray(a.instances) && a.instances.length
      ? a.instances
      : [{ uri: null, method: null, param: null }];

    for (const it of inst){
      const url    = it.uri || it.url || null;
      const method = normMethod(it.method);
      const param  = normParam(it.param);

      const signature = { pluginid, title, url, method, param };

      rows.push({
        tool: 'zaproxy',
        title, pluginid, severity,
        description: desc,
        scanner_confidence: conf,
        cwe,
        site_owner: siteOwner,
        url, method, param,
        signature,
        guidance: guidance || null
      });
    }
  }
  return rows;
}

// --- Checkov (separate mapping + fingerprint)
function parseCheckov(scan){
  const docs = Array.isArray(scan) ? scan : [scan];
  const rows = [];

  for (const doc of docs){
    const check_type = doc?.check_type || null;
    const failed = doc?.results?.failed_checks || [];
    if (!Array.isArray(failed)) continue;

    for (const v of failed){
      const check_id   = v.check_id || v.bc_check_id || null;
      const title      = (v.check_name || 'Checkov Finding').trim();
      const severity   = sevCheckov(v.severity);
      const result     = v.check_result?.result || '';
      const guideline  = v.guideline || '';
      const repo_owner = v['Repo Owner'] ?? v.repo_owner ?? null;
      const repo_link  = normRepoUrl(v['Repo Link']  ?? v.repo_link  ?? null);

      const file_path  = normPath(v.repo_file_path || v.file_abs_path || v.file_path || null);
      const resource   = v.resource || v.resource_address || null;

      let description = '';
      if (check_type) description += `Check Type: ${check_type}\n`;
      description += `Check Name: ${title}\n`;
      if (result)     description += `Result: ${result}\n`;
      if (check_id)   description += `Check Id: ${check_id}\n`;
      if (repo_owner) description += `Repo Owner: ${repo_owner}\n`;
      if (repo_link)  description += `Repo Link: ${repo_link}\n`;
      if (file_path)  description += `File: ${file_path}\n`;
      if (resource)   description += `Resource: ${resource}\n`;
      if (guideline)  description += `Guideline: ${guideline}\n`;

      const signature = {
        pluginid: String(check_id || ''),
        check_type: check_type || null,
        repo: repo_link || null,
        file_path: file_path || null,
        resource: resource || null
      };

      rows.push({
        tool: 'checkov',
        title,
        pluginid: String(check_id || ''),
        severity,
        description,
        scanner_confidence: null,
        cwe: v.cwe || null,
        site_owner: repo_owner ?? null,
        url: repo_link || null,
        method: null,
        param: null,
        file_path,
        signature,
        guidance: guideline || null
      });
    }
  }

  return rows;
}

// --- TruffleHog (only safe, no raw secrets)
function parseTrufflehog(scan){
  const docs = Array.isArray(scan) ? scan : [scan];
  const rows = [];

  for (const v of docs){
    if (!v || typeof v !== 'object') continue;

    const detector     = v.DetectorName || `Detector-${v.DetectorType ?? ''}`.trim();
    const title        = `TruffleHog: ${detector}`;
    const repo_owner   = v['Repo Owner'] ?? null;
    const repo_link    = normRepoUrl(v['Repo Link'] ?? null) || null;

    const file_path    = normPath(v.SourceMetadata?.Data?.Filesystem?.file || null);
    const line         = v.SourceMetadata?.Data?.Filesystem?.line ?? null;

    const redacted     = v.Redacted || null;
    const decodedHint  = v.DecoderName ? `Decoder: ${v.DecoderName}` : null;

    // Severity heuristic
    let severity = 'Medium';
    const highDetectors = new Set(['AWS','Github','GitHub','PrivateKey','Slack','Google','Azure','GCP','JWT']);
    if (v.Verified === true || highDetectors.has(detector)) severity = 'High';

    // Description (no raw)
    let description = '';
    if (file_path) description += `File: ${file_path}${line!=null ? `:${line}`:''}\n`;
    description += `Detector: ${detector}\n`;
    if (decodedHint) description += `${decodedHint}\n`;
    if (redacted) description += `Redacted: ${redacted}\n`;
    if (v.ExtraData?.account) description += `Account: ${v.ExtraData.account}\n`;
    if (v.ExtraData?.resource_type) description += `Resource: ${v.ExtraData.resource_type}\n`;
    if (v.ExtraData?.username) description += `User: ${v.ExtraData.username}\n`;
    if (v.ExtraData?.url) description += `URL: ${v.ExtraData.url}\n`;

    // Guidance
    const guideUrl = v.ExtraData?.rotation_guide || null;
    const guidanceParts = [];
    if (guideUrl) guidanceParts.push(`Rotate/disable secret: ${guideUrl}`);
    if (detector.toLowerCase().includes('aws')) guidanceParts.push('Invalidate and rotate AWS access key; review IAM usage');
    if (detector.toLowerCase().includes('privatekey')) guidanceParts.push('Revoke exposed private key and replace associated credentials');
    const guidance = guidanceParts.length ? guidanceParts.join(' | ') : 'Remove the secret from history and rotate associated credentials';

    // Fingerprint (no secret content)
    const signature = {
      detector,
      repo: repo_link || null,
      file_path: file_path || null,
      line: line ?? null
    };

    rows.push({
      tool: 'trufflehog',
      title,
      pluginid: detector, // keep detector as rule id
      severity,
      description,
      scanner_confidence: null,
      cwe: null,
      site_owner: repo_owner || null,
      url: v.ExtraData?.url || repo_link || null,
      method: null,
      param: null,
      file_path,
      signature,
      guidance
    });
  }

  return rows;
}

// --- Kubescape (only FAILED)
function parseKubescape(scan){
  const rows = [];
  const sd = scan?.summaryDetails;
  if (!sd) return rows;

  let controls = sd.controls;

  // Normalize controls into an array
  let list = [];
  if (Array.isArray(controls)) {
    list = controls;
  } else if (controls && typeof controls === 'object') {
    list = Object.values(controls);
  }

  // Some exports embed additional array entries directly under summaryDetails (bad JSONs)
  // Try to append any array-like entries if present
  if (Array.isArray(sd)) list = list.concat(sd);

  for (const c of list){
    if (!c) continue;

    const status = ksStatus(c);
    if (String(status).toLowerCase() !== 'failed') continue; // only failed

    const controlID = c.controlID || c.id || null;
    const name      = c.name || 'Kubescape Control';
    const repo_owner= c['Repo Owner'] ?? null;
    const repo_link = normRepoUrl(c['Repo Link'] ?? null) || null;

    const score     = c.score ?? c.complianceScore ?? null;
    const severity  = ksSeverityFromScore(score);

    // Extract first failed rule & path (if available)
    let ruleName = null, failedPath = null;
    const rules = Array.isArray(c.rules) ? c.rules : [];
    for (const r of rules){
      if ((r.status || '').toLowerCase() === 'failed' || (r?.status?.status || '').toLowerCase() === 'failed'){
        ruleName = r.name || null;
        const paths = Array.isArray(r.paths) ? r.paths : [];
        if (paths.length){
          failedPath = paths[0].failedPath || paths[0].reviewPath || null;
        }
        break;
      }
    }

    // Description
    let description = '';
    description += `Control: ${controlID || ''} - ${name}\n`;
    description += `Status: ${status}\n`;
    if (score != null) description += `Score: ${score}\n`;
    if (ruleName) description += `Rule: ${ruleName}\n`;
    if (failedPath) description += `Failed Path: ${failedPath}\n`;
    if (repo_owner) description += `Repo Owner: ${repo_owner}\n`;
    if (repo_link)  description += `Repo Link: ${repo_link}\n`;

    // Guidance
    const guidance = ruleName
      ? `Review and tighten permissions to satisfy rule: ${ruleName}${failedPath ? ` (failed at: ${failedPath})` : ''}`
      : 'Review the failing control and remediate misconfigurations';

    // Fingerprint
    const signature = {
      pluginid: String(controlID || ''),
      repo: repo_link || null,
      rule: ruleName || null,
      failedPath: failedPath || null
    };

    rows.push({
      tool: 'kubescape',
      title: name,
      pluginid: String(controlID || ''),
      severity,
      description,
      scanner_confidence: null,
      cwe: null,
      site_owner: repo_owner || null,
      url: repo_link || null,
      method: null,
      param: null,
      file_path: null,
      signature,
      guidance
    });
  }

  return rows;
}

// --- Trivy (pkg pulled out as its own field)
function parseTrivy(scan){
  const rows = [];
  if (!scan || !Array.isArray(scan.Results)) return rows;

  const artifactName = scan.ArtifactName || null;
  const imageID      = scan.Metadata?.ImageID || null;

  for (const res of scan.Results){
    const target = res?.Target || null;
    const vulns  = Array.isArray(res?.Vulnerabilities) ? res.Vulnerabilities : [];

    for (const v of vulns){
      const cve        = v.VulnerabilityID || '';
      const title      = v.Title || cve || 'Trivy Finding';
      const severity   = sevTrivyLevel(v.Severity);
      const pkg        = v.PkgName || null;          // <- pulled out
      const installed  = v.InstalledVersion || null;
      const fixed      = v.FixedVersion || null;
      const status     = v.Status || null;
      const purl       = v.PkgIdentifier?.PURL || null;
      const primaryURL = v.PrimaryURL || null;
      const cwe        = Array.isArray(v.CweIDs) && v.CweIDs.length ? v.CweIDs[0] : null;

      const imageName  = v['Image Name']  || artifactName || null;
      const imageOwner = v['Image Owner'] || null;

      // Description (pkg omitted here by request)
      let description = '';
      if (imageName)  description += `Image: ${imageName}\n`;
      if (target)     description += `Target: ${target}\n`;
      if (installed)  description += `Installed: ${installed}\n`;
      if (fixed)      description += `Fixed: ${fixed}\n`;
      if (status)     description += `Status: ${status}\n`;
      if (purl)       description += `PURL: ${purl}\n`;
      if (primaryURL) description += `Reference: ${primaryURL}\n`;
      if (v.Description) description += `\n${v.Description}\n`;

      // Guidance
      const tips = [];
      if (fixed && pkg) tips.push(`Upgrade ${pkg} to ${fixed} or later`);
      if (primaryURL)   tips.push(`See advisory: ${primaryURL}`);
      const guidance = tips.length ? tips.join(' | ') : null;

      // Fingerprint (no site_owner)
      const signature = {
        pluginid: String(cve),
        artifact: imageID || imageName || artifactName || null,
        target:   target || null,
        pkg:      pkg || null,
        installed:installed || null
      };

      rows.push({
        tool: 'trivy',
        title,
        pluginid: String(cve),
        severity,
        description,
        scanner_confidence: null,
        cwe,
        site_owner: imageOwner || null, // e.g., "jacky"
        url: primaryURL || null,
        method: null,
        param: null,
        file_path: null,
        signature,
        guidance,
        pkg // <- exposed separately
      });
    }
  }
  return rows;
}

// ====== MAIN ======
const now = new Date().toISOString();
const inputItems = $input.all();
const out = [];

for (const item of inputItems){
  const j = item.json || {};

  // Source payload from "Extract from file"
  const scan        = j.scan ?? j.data ?? j.report ?? j.content ?? j.payload ?? {};
  const hintedTool  = j.tool ? String(j.tool).toLowerCase() : null;
  const mainIndex   = j.mainIndex   || 'security-findings';
  const eventsIndex = j.eventsIndex || 'security-findings-events';

  // s3 ONLY from this item (prevents cross-run leakage)
  const s3 = (j.s3 && j.s3.bucket && j.s3.key)
    ? { bucket: j.s3.bucket, key: j.s3.key }
    : (j.bucket && j.key)
      ? { bucket: j.bucket, key: j.key }
      : null;

  // Tool detection
  let tool = hintedTool;
  if (!tool){
    if (Array.isArray(scan) && scan.some(d => d?.results?.failed_checks)) tool = 'checkov';
    else if (scan?.results?.failed_checks) tool = 'checkov';
    else if (Array.isArray(scan) && scan.some(d => d?.DetectorName || d?.SourceMetadata)) tool = 'trufflehog';
    else if (scan?.summaryDetails) tool = 'kubescape';
    else if (scan?.Results && Array.isArray(scan.Results) && scan.Results.some(r => Array.isArray(r?.Vulnerabilities))) tool = 'trivy';
    else if (scan?.site || (Array.isArray(scan) && scan.some(d => d?.site))) tool = 'zaproxy';
    else tool = 'unknown';
  }

  let findings = [];
  if (tool === 'zaproxy') findings = parseZap(scan);
  else if (tool === 'checkov') findings = parseCheckov(scan);
  else if (tool === 'trufflehog') findings = parseTrufflehog(scan);
  else if (tool === 'kubescape') findings = parseKubescape(scan);
  else if (tool === 'trivy') findings = parseTrivy(scan);
  else findings = [];

  // De-dupe within this item only
  const seen = new Set();

  for (const f of findings){
    const fingerprint = fingerprintOf(f.tool, f.signature);
    if (seen.has(fingerprint)) continue;
    seen.add(fingerprint);

    const mainDoc = {
      '@timestamp': now,
      tool: f.tool,
      title: f.title,
      severity: f.severity,
      description: f.description || '',
      scanner_confidence: f.scanner_confidence ?? null,
      site_owner: f.site_owner ?? null,
      cwe: f.cwe || null,
      pluginid: f.pluginid || null,
      url: f.url ?? null,
      method: f.method ?? null,
      param: f.param ?? null,
      guidance: f.guidance ?? null,
      // Optional extras per tool
      ...(f.file_path ? { file_path: f.file_path } : {}),
      ...(f.pkg ? { pkg: f.pkg } : {}),
      dedupe: { fingerprint, signature: f.signature }
    };

    const eventDoc = {
      '@timestamp': now,
      type: 'observation',
      fingerprint,
      tool: f.tool,
      title: f.title,
      severity: f.severity
    };

    if (s3){ mainDoc.s3 = s3; eventDoc.s3 = s3; }

    out.push({
      json: {
        now,
        fingerprint,
        mainIndex,
        eventsIndex,
        mainDoc,
        eventDoc
      }
    });
  }
}

return out;

// === Extra-safe Group & Collapse ===
// - Groups by fingerprint
// - Carries per-item indices, then picks a group-consistent index
// - Aggregates endpoints and file paths
// - Unions all S3 source objects (from both mainDoc/eventDoc)
// - Never reads indices from $json (avoids cross-item bleed)

// ---------- helpers ----------
const uniq = arr => Array.from(new Set((arr || []).filter(v => v != null && v !== '')));

function uniqSources(list) {
  const seen = new Set(), out = [];
  for (const s of list || []) {
    if (!s || !s.bucket || !s.key) continue;
    const id = `${s.bucket}|${s.key}`;
    if (seen.has(id)) continue;
    seen.add(id);
    out.push({ bucket: s.bucket, key: s.key });
  }
  return out;
}

// ---------- collect & group ----------
const groups = new Map();

for (const it of $input.all()) {
  const j = it.json || {};
  const fp = j.fingerprint;
  if (!fp) continue;

  const md = j.mainDoc || {};
  const ed = j.eventDoc || {};
  const mainIndex   = j.mainIndex   || 'security-findings';
  const eventsIndex = j.eventsIndex || 'security-findings-events';

  const arr = groups.get(fp) || [];
  arr.push({ md, ed, mainIndex, eventsIndex });
  groups.set(fp, arr);
}

// ---------- build outputs ----------
const out = [];

for (const [fp, arr] of groups) {
  if (!arr.length) continue;

  const first = arr[0].md || {};
  const occurrences_delta = arr.length;

  // endpoints (URLs) & file paths across occurrences
  const endpoints  = uniq(arr.map(x => x.md && x.md.url));
  const filePaths  = uniq(arr.map(x => x.md && x.md.file_path));

  // all s3 sources from mainDoc + eventDoc
  const s3Candidates = [
    ...arr.map(x => x.md && x.md.s3),
    ...arr.map(x => x.ed && x.ed.s3),
  ];
  const sources = uniqSources(s3Candidates);

  // choose indices safely from the group's own items
  const mainIdxSet   = new Set(arr.map(x => x.mainIndex).filter(Boolean));
  const eventsIdxSet = new Set(arr.map(x => x.eventsIndex).filter(Boolean));
  const groupMainIndex   = mainIdxSet.size   ? [...mainIdxSet][0]   : 'security-findings';
  const groupEventsIndex = eventsIdxSet.size ? [...eventsIdxSet][0] : 'security-findings-events';

  // optional warnings if mixed indices found within a group
  const warnings = [];
  if (mainIdxSet.size > 1)   warnings.push(`Mixed mainIndex for fingerprint ${fp}: ${[...mainIdxSet].join(', ')}`);
  if (eventsIdxSet.size > 1) warnings.push(`Mixed eventsIndex for fingerprint ${fp}: ${[...eventsIdxSet].join(', ')}`);

  // merge main doc: keep the first occurrence as the base,
  // but null-out per-occurrence HTTP fields and add aggregates.
  const mergedMain = {
    ...first,
    url: null,
    method: null,
    param: null,
  };
  if (endpoints.length) mergedMain.endpoints = endpoints;
  if (filePaths.length) mergedMain.file_paths = filePaths;

  // aggregate event: keep first's basics, attach count; keep first's s3 as canonical
  const aggEvent = {
    '@timestamp': first['@timestamp'] || new Date().toISOString(),
    type: 'observation',
    fingerprint: fp,
    tool: first.tool,
    title: first.title,
    severity: first.severity,
    count: occurrences_delta,
    s3: first.s3 || (sources.length ? sources[0] : undefined),
  };

  out.push({
    json: {
      fingerprint: fp,
      now: aggEvent['@timestamp'],
      mainIndex: groupMainIndex,
      eventsIndex: groupEventsIndex,
      occurrences_delta,
      mainDoc: mergedMain,
      eventDoc: aggEvent,
      sources,
      ...(warnings.length ? { warnings } : {})
    }
  });
}

return out;

function union(a, b){ const A=Array.isArray(a)?a:[], B=Array.isArray(b)?b:[]; const s=new Set(), out=[]; for (const x of [...A,...B]) if (x!=null && !s.has(x)) { s.add(x); out.push(x); } return out; }

const prev = $items('Collapse by Fingerprint');
const got  = $input.all();

const out = [];
for (let i = 0; i < got.length; i++) {
  const esItem   = got[i].json || {};
  const baseItem = (prev[i] && prev[i].json) ? prev[i].json : {};

  const existing = esItem.Document || esItem._source || null;
  const incoming = baseItem.mainDoc || {};
  const now      = baseItem.now;
  const delta    = baseItem.occurrences_delta || 1;

  const merged = existing ? {
    ...existing,
    ...incoming,
    occurrences: (existing.occurrences || 0) + delta,
    last_seen: now,
    endpoints: union(existing.endpoints, incoming.endpoints)
  } : {
    ...incoming,
    occurrences: delta,
    last_seen: now
  };

  out.push({
    json: {
      exists: !!existing,
      index: baseItem.mainIndex,
      id: baseItem.fingerprint,
      doc: merged,
      eventsIndex: baseItem.eventsIndex,
      eventDoc: baseItem.eventDoc,
      // 👇 carry forward all files to move
      sources: baseItem.sources,
      // optional: processed config from defaults if you added them earlier
      processedPrefix: baseItem.processedPrefix,
      processedBucket: baseItem.processedBucket
    }
  });
}
return out;

function cleanPrefix(p){
  let x = (p || 'processed/').toString().trim();
  x = x.replace(/^\/+/, '');       // no leading slash
  if (!x.endsWith('/')) x += '/';  // ensure trailing slash
  return x;
}

const prefix = cleanPrefix($json.processedPrefix);
const processedBucket = $json.processedBucket || null;

// prefer the union list from Collapse → Build; fallback to single doc.s3
const srcs = Array.isArray($json.sources) ? $json.sources
           : ($json.doc?.s3 ? [ $json.doc.s3 ] : []);

return srcs
  .filter(s => s && s.bucket && s.key)
  .map(s => {
    const sourcePath = `/${s.bucket}/${s.key}`;
    const destBucket = processedBucket || s.bucket;
    const destKey = `${prefix}${s.key}`;
    const destPath = `/${destBucket}/${destKey}`;
    return { json: {
      source: s,             // { bucket, key }
      sourcePath,            // "bucket/key"
      dest: { bucket: destBucket, key: destKey },
      destPath               // "bucket/prefix/key"
    }};
  });
